From 9626dbb41aa2226409e56cc0e4c5d010fe93e98f Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Sat, 21 Nov 2026 14:21:24 +0100
Subject: [PATCH] xwayland: Forward presses on Wayland windows to grabbing X11
 popups

X11 menus close when their pointer grab sees a press outside of them,
but presses on Wayland windows never reached Xwayland, so menus like
those of xembed tray icons stayed open. Now these presses reach it.

BUG: 453946
---
 src/input.h               |  1 +
 src/xwayland/xwayland.cpp | 80 +++++++++++++++++++++++++++++++++++++++
 src/xwayland/xwayland.h   |  2 +
 3 files changed, 83 insertions(+)

diff --git a/src/input.h b/src/input.h
index 068644eb63..7829633150 100644
--- a/src/input.h
+++ b/src/input.h
@@ -384,6 +384,7 @@ enum Order {
     Effects,
     InteractiveMoveResize,
     Popup,
+    XwaylandPopup,
     Decoration,
     WindowAction,
     XWayland,
diff --git a/src/xwayland/xwayland.cpp b/src/xwayland/xwayland.cpp
index 852b728baf..66bf20b5c5 100644
--- a/src/xwayland/xwayland.cpp
+++ b/src/xwayland/xwayland.cpp
@@ -26,6 +26,7 @@
 #include "window.h"
 #include "workspace.h"
 #include "x11eventfilter.h"
+#include "x11window.h"
 #include "xkb.h"
 #include "xwayland/databridge.h"
 #include "xwayland/dnd.h"
@@ -332,6 +333,81 @@ public:
     bool m_filterMouse = false;
 };

+class XwaylandPopupGrabFilter : public KWin::InputEventFilter
+{
+public:
+    XwaylandPopupGrabFilter()
+        : KWin::InputEventFilter(InputFilterOrder::XwaylandPopup)
+    {
+    }
+
+    bool pointerButton(KWin::PointerButtonEvent *event) override
+    {
+        ClientConnection *xwaylandClient = waylandServer()->xWaylandConnection();
+        if (!xwaylandClient) {
+            return false;
+        }
+
+        auto pointer = waylandServer()->seat()->pointer();
+        if (event->state == PointerButtonState::Released) {
+            if (!m_pressedButtons.remove(event->nativeButton)) {
+                return false;
+            }
+        } else {
+            const SurfaceInterface *surface = pointer->focusedSurface();
+            if (surface && surface->client() == xwaylandClient) {
+                return false;
+            }
+            if (!hasX11Popup() || !isX11PointerGrabbed()) {
+                return false;
+            }
+            m_pressedButtons.insert(event->nativeButton);
+            warpX11Pointer(event->position);
+        }
+
+        // Let the X11 client that grabbed the pointer see the press, as it would on X11
+        waylandServer()->seat()->setTimestamp(event->timestamp);
+        pointer->sendButton(event->nativeButton, event->state, xwaylandClient);
+        return true;
+    }
+
+private:
+    static bool hasX11Popup()
+    {
+        const auto windows = workspace()->windows();
+        return std::any_of(windows.cbegin(), windows.cend(), [](const Window *window) {
+            const auto x11Window = qobject_cast<const X11Window *>(window);
+            return x11Window && x11Window->isUnmanaged() && x11Window->isPopupWindow() && x11Window->isShown();
+        });
+    }
+
+    static bool isX11PointerGrabbed()
+    {
+        xcb_connection_t *connection = kwinApp()->x11Connection();
+        const xcb_grab_pointer_cookie_t cookie = xcb_grab_pointer(connection, false, kwinApp()->x11RootWindow(), 0,
+                                                                  XCB_GRAB_MODE_ASYNC, XCB_GRAB_MODE_ASYNC, XCB_WINDOW_NONE, XCB_CURSOR_NONE, XCB_CURRENT_TIME);
+        UniqueCPtr<xcb_grab_pointer_reply_t> reply(xcb_grab_pointer_reply(connection, cookie, nullptr));
+        if (!reply) {
+            return false;
+        }
+        if (reply->status == XCB_GRAB_STATUS_SUCCESS) {
+            xcb_ungrab_pointer(connection, XCB_CURRENT_TIME);
+            xcb_flush(connection);
+        }
+        return reply->status == XCB_GRAB_STATUS_ALREADY_GRABBED;
+    }
+
+    static void warpX11Pointer(const QPointF &position)
+    {
+        xcb_connection_t *connection = kwinApp()->x11Connection();
+        const QPoint nativePosition = Xcb::toXNative(position);
+        xcb_warp_pointer(connection, XCB_WINDOW_NONE, kwinApp()->x11RootWindow(), 0, 0, 0, 0, nativePosition.x(), nativePosition.y());
+        Xcb::sync(connection);
+    }
+
+    QSet<quint32> m_pressedButtons;
+};
+
 XwaylandStartupScripts::XwaylandStartupScripts()
 {
 }
@@ -470,6 +546,7 @@ void Xwayland::handleXwaylandFinished()
     m_startupScripts.reset();
     m_dataBridge.reset();
     m_inputFilter.reset();
+    m_popupGrabFilter.reset();
     m_xrandrEventsFilter.reset();

     destroyX11Connection();
@@ -491,6 +568,9 @@ void Xwayland::handleXwaylandReady()

     m_xrandrEventsFilter = std::make_unique<XrandrEventFilter>(this);

+    m_popupGrabFilter = std::make_unique<XwaylandPopupGrabFilter>();
+    input()->installInputEventFilter(m_popupGrabFilter.get());
+
     refreshEavesdropping();
     connect(options, &Options::xwaylandEavesdropsChanged, this, &Xwayland::refreshEavesdropping);
     connect(options, &Options::xwaylandEavesdropsMouseChanged, this, &Xwayland::refreshEavesdropping);
diff --git a/src/xwayland/xwayland.h b/src/xwayland/xwayland.h
index bccb7c3ee2..6e54ae440b 100644
--- a/src/xwayland/xwayland.h
+++ b/src/xwayland/xwayland.h
@@ -33,6 +33,7 @@ namespace Xwl

 class XrandrEventFilter;
 class XwaylandInputFilter;
+class XwaylandPopupGrabFilter;
 class XwaylandLauncher;
 class DataBridge;

@@ -114,6 +115,7 @@ private:
     std::unique_ptr<XwaylandLauncher> m_launcher;
     std::unique_ptr<XwaylandStartupScripts> m_startupScripts;
     std::unique_ptr<XwaylandInputFilter> m_inputFilter;
+    std::unique_ptr<XwaylandPopupGrabFilter> m_popupGrabFilter;

     Q_DISABLE_COPY(Xwayland)
 };
